        sem_id = _get_semester_id(cur, ay, term)
        cur.execute("""
            DELETE FROM public.subject_faculty_assignment
            WHERE UPPER(programcode)   = UPPER(%s)
              AND yearlevel            = %s
              AND semesterid           = %s
              AND UPPER(subjectcode)   = UPPER(%s)
        """, (program, int(year_level), sem_id, subjectcode.upper()))
